entries[90622] = { ["name"] = "Winziger Bronzeskorpion", ["text"] = "Wirken in 3 sek. 5\nAllem Anschein nach war dies einst ein lebendiger Skorpion, der in Bronze getaucht wurde, um ihn zu konservieren. Auf der Unterseite steht in Orcisch geschrieben: \"Der Häuptling lacht über Eure erbärmlichen Mordversuche.\"\nWinziger Bronzeskorpion\nWird beim Aufheben gebunden" }
