entries[90734] = { ["name"] = "Grimmige Wolfsfigur", ["text"] = "Wirken in 3 sek. 5\nWölfe haben wahrscheinlich bereits seit Jahrhunderten an der Seite der Orcs gelebt. Als die Orcs Azeroth durch das Dunkle Portal betraten, kamen die Wölfe mit ihnen. Diese Figurine wurde liebevoll ausgeführt, bis hin zu dem Draeneiarm, der von den winzigen, geifernden Lefzen umklammert wird.\nGrimmige Wolfsfigur\nWird beim Aufheben gebunden" }
