entries[90831] = { ["name"] = "Teuflische Peitsche", ["text"] = "Wirken in 3 sek. 5\nDie Hexenmeister gewannen unter den Orcs mit Gul'dans Aufstieg an die Macht an Bedeutung. Diese Peitsche eines Sukkubus ist aus dem Leder veschiedener Kreaturen geflochten - einige davon wahrscheinlich Humanoide.\nTeuflische Peitsche\nWird beim Aufheben gebunden" }
entries[90832] = { ["name"] = "Glasierte Lehmkachel", ["text"] = "Wirken in 3 sek. 5\nEinstmals müssen viele dieser Kacheln die Wände oder den Boden einer Festung oder eines Empfangssaals auf Draenor geziert haben. Auf diesem Stück ist ein Landstrich dargestellt, der dem heutigen Nagrand sehr ähnelt, auf einem Feld aus gelber und grüner Glasur weiden Herdentiere. Der Rand ist mit einem schwarz-braunen Schachbrettmuster verziert.\nGlasierte Lehmkachel\nWird beim Aufheben gebunden" }
entries[90833] = { ["name"] = "Trinkschädel", ["text"] = "Wirken in 3 sek. 5\nDieses Gefäß sieht gefährlich aus. Durch einen Designfehler sickert sein Inhalt jedoch durch die Augenhöhlen aus. Duuuurst...\nTrinkschädel\nWird beim Aufheben gebunden" }
