entries[90853] = { ["name"] = "Fußkette mit goldenen Glöckchen", ["text"] = "Wirken in 3 sek. 5\nDieses schlanke Kettchen aus purpurnem Metall ist mit siebzehn kleinen Glöckchen und etwas größeren, braunen Glasperlen geschmückt. Möglicherweise trug es einst eine Tänzerin oder eine junge Dame der Gesellschaft.\nFußkette mit goldenen Glöckchen\nWird beim Aufheben gebunden" }
