entries[90855] = { ["name"] = "Item - Stacking Spell Power", ["text"] = "Eure Zauber gewähren Euch 15 Sek. lang 29 Zaubermacht. Bis zu 6-mal stapelbar." }
entries[90860] = { ["name"] = "Geschnitzte Harfe aus exotischem Holz", ["text"] = "Wirken in 3 sek. 5\nWie eine Lyra wurde diese kleine Harfe in einer Hand gehalten. Sie hat einen tiefen hölzernen Korpus und sieben Saiten, die um ein Stimmholz geknotet sind. Es ist durchaus noch möglich, auf diesem Instrument Musik zu spielen, allerdings haben alle Töne eine melancholische Färbung...\nGeschnitzte Harfe aus exotischem Holz\nWird beim Aufheben gebunden" }
entries[90861] = { ["name"] = "Seltsamer silberner Briefbeschwerer", ["text"] = "Wirken in 3 sek. 5\nWenn dieses Objekt von den Draenei nicht als Briefbeschwerer benutzt wurde, dann habt Ihr keine Ahnung, wofür es gut ist. Es ist einfach ein großer Tropfen versteinerten Quecksilbers, der auf einer Seite abgeflacht ist, um auf einem Tisch abgelegt werden zu können.\nSeltsamer silberner Briefbeschwerer\nWird beim Aufheben gebunden" }
entries[90864] = { ["name"] = "Szepter der Nathrezim", ["text"] = "Wirken in 3 sek. 5\nDie Nathrezim, auch als Schreckenslords bekannt, sind die Geheimagenten und Folterspezialisten der Brennenden Legion. Auch wenn sie auf dem Schlachtfeld beeindruckende Gegner sind, bevorzugen sie es, ihre Feinde durch Manipulation und List gegeneinander aufzubringen.\nSzepter der Nathrezim\nWird beim Aufheben gebunden" }
