entries[90949] = { ["name"] = "Verschlingende Flammen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht an allen Feinden vor Valiona 40000 Schattenschaden. Verschlingende Flammen verursachen weniger Schaden je weiter der Gegner von Valiona entfernt ist." }
entries[90950] = { ["name"] = "Verschlingende Flammen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2.5 sek.\n'Verschlingende Flammen' verursacht alle 1 Sek. 40000 Schattenschaden. Der Schaden lässt nach, je weiter das Ziel vom Ursprung der verschlingenden Flammen entfernt ist." }
