entries[90954] = { ["name"] = "Camouflage", ["text"] = "Sofort 2 min Abklingzeit\nWird eins mit der Umgebung und kann nicht zum Ziel von Distanzangriffen werden." }
entries[90956] = { ["name"] = "Schattenschritt", ["text"] = "40 Meter Reichweite\nSofort\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen." }
entries[90958] = { ["name"] = "Entrinnen", ["text"] = "Sofort\nErhöht die Ausweichchance des Zaubernden um 35%." }
entries[90960] = { ["name"] = "Wirbelnde Klingen", ["text"] = "40 Energie 35 Meter Reichweite\nSofort\nBenötigt Waffen\nUmgibt den Feind mit wirbelnden Klingen. Verursacht bei allen in der Nähe befindlichen Einheiten körperlichen Schaden." }
