entries[90968] = { ["name"] = "Barocke Schwertscheide", ["text"] = "Wirken in 3 sek. 5\nDiese Schwertscheide ist so überladen, dass sie schon fast geschmacklos ist. Jeder noch so kleine Teil der Oberfläche wurde verziert, vergoldet oder mit Inschriften versehen. Es ist wahrscheinlich, dass die Waffe, zu der diese Scheide einst gehörte, entweder ein hohes magisches Potenzial hatte oder zu wichtigen zeremoniellen Zwecken diente.\nBarocke Schwertscheide\nWird beim Aufheben gebunden" }
entries[90969] = { ["name"] = "Cancel Invisibility Detection" }
entries[90971] = { ["name"] = "Geistabsorption" }
entries[90974] = { ["name"] = "Feiner Kristallkandelaber", ["text"] = "Wirken in 3 sek. 5\nDieser Leuchter war für ein ganzes Dutzend Kerzen bestimmt. Blaue und violette Kristalle, untereinander mit feinen Kettchen verbunden, fließen wie Regentropfen an den ornamentverzierten Verstrebungen hinab. Die Initialen des Künstlers sind an einer unauffälligen Stelle eingraviert: 'V. T.'\nFeiner Kristallkandelaber\nWird beim Aufheben gebunden" }
entries[90975] = { ["name"] = "Würdevolles Porträt", ["text"] = "Wirken in 3 sek. 5\nEin sehr ernsthaftes Porträt eines sehr ernsthaften Draenei. Die Abbildung des Herren ist durchaus schmeichelnd, trotzdem beschleicht Euch das Gefühl, dass der Künstler dem Porträtierten nicht wohlgesinnt war. Ein scharfer Blick an den ganz unteren Rand enthüllt, dass der gute Mann offenbar keine Hose trägt.\nWürdevolles Porträt\nWird beim Aufheben gebunden" }
entries[90976] = { ["name"] = "Ruf der Banshee", ["text"] = "45 Meter Reichweite\nSofort\nRuft eine Banshee herbei, um einen verwundeten SI:7-Agenten fortzutransportieren. Das Ziel muss über 35% Gesundheit oder weniger verfügen." }
entries[90977] = { ["name"] = "Geistsprecher beschwören" }
entries[90978] = { ["name"] = "Energie!", ["text"] = "Wirken in 3 sek.\nErhöht das Angriffs- und Zaubertempo des Zaubernden um 50% und den von ihm verursachten Schaden um 25%." }
entries[90980] = { ["name"] = "Spalten", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Feind und seinen nächsten Verbündeten 150% des normalen Nahkampfschadens zu, wirkt auf bis zu 3 Ziele." }
entries[90983] = { ["name"] = "Ankunft der Naaru", ["text"] = "Wirken in 3 sek. 15\nDer Kristall scheint eine Art magisches Aufnahmegerät zu sein. Die gespeicherte Nachricht wird in einer Sprache abgespielt, die Ihr nicht vollständig verstehen könnt, Ihr glaubt jedoch, dass sie entweder die Aufnahme oder eine Nachstellung des ersten Kontakts der Eredar mit den Naaru ist.\nAnkunft der Naaru\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Seht Euch eine Aufnahme von der Ankunft der Naaru an. (3 Min Abklingzeit)" }
entries[90984] = { ["name"] = "Die letzte Reliquie von Argus", ["text"] = "Wirken in 3 sek. 15\nBevor sie auf Azeroth oder Draenor lebten, war die Heimat der Draenei, die sich damals noch Eredar nannten, der Planet Argus. Als Sargeras seine Aufmerksamkeit auf Argus richtete, floh Prophet Velen mit einigen seines Volkes, die sich daraufhin Draenei nannten. Die zurückbleibenden Eredar wurden Teil der Brennenden Legion. Während Velens Flucht nahm jemand diesen einfachen Kristall mit. Eine Inschrift auf der Unterseite lautet \"Ich sehne mich nach Mac'Aree\".\nDie letzte Reliquie von Argus\nWird beim Aufheben gebunden\nBenutzen: Teleportiert Euch exakt dorthin, wo Ihr hinwollt... sofern Ihr nicht allzu wählerisch seid. (12 Std. Abklingzeit)\n\"Einer der wenigen Gegenstände, den die Draenei auf ihrer Flucht von Argus mitnehmen konnten.\"" }
entries[90985] = { ["name"] = "Tote Winde", ["text"] = "Sofort\nErhöht die Zaubermacht 15 Sek. lang um 17." }
entries[90986] = { ["name"] = "Item - Proc Stacking Spell Power", ["text"] = "Eure regelmäßigen Heil- und Schadenszauber gewähren Euch jedes Mal, wenn sie heilen oder Schaden verursachen, 17 Zaubermacht. Hält 15 Sek. lang an. Bis zu 20-mal stapelbar.\n(500ms Abklingzeit)" }
entries[90987] = { ["name"] = "Beschlagener Elekktreibstock", ["text"] = "Wirken in 3 sek. 5\nElekk sind mammutähnliche Kreaturen, die auf Draenor heimisch sind, insbesondere in Nagrand. Die Draenei domestizierten Elekk, um sie als Reittiere zu nutzen. Dieser Treibstock ist ein langer und spitzer Stab, der dazu dient, sture Elekk zu motivieren, deren Ausbildung noch nicht abgeschlossen ist.\nBeschlagener Elekktreibstock\nWird beim Aufheben gebunden" }
entries[90988] = { ["name"] = "Komplizierter Schatztruhenschlüssel", ["text"] = "Wirken in 3 sek. 5\nObwohl die Technologie der Vrykul im allgemeinen hinter der der Horde oder Allianz zurückbleibt, ist die Komplexität dieses einfachen Schlüssels schier unglaublich. In der Kultur der Vrykul ist es üblich, dass die Frau des Haushalts die Schlüssel hütet und sie offen trägt, um ihren Status zu zeigen.\n\n\"Öffnet die Truhe von Dunkelkleriker Salem ganz sicher nicht.\"\nKomplizierter Schatztruhenschlüssel\nWird beim Aufheben gebunden" }
