entries[91004] = { ["name"] = "Heiliges Feuer", ["text"] = "1000 Mana 30 Meter Reichweite\nWirken in 5 sek.\nVerzehrt einen Feind mit Flammen, verbrennt ihn und fügt ihm im Verlauf von 8 Sek. alle 2 Sek. zusätzlichen Feuerschaden zu." }
