entries[91008] = { ["name"] = "Skramasax", ["text"] = "Wirken in 3 sek. 5\nEin Skramasax ist eine lange, gerade und einschneidige Klinge mit einem simplen Griff, die von vielen Vrykulkriegern als Zweitwaffe getragen wird. Ein weitverbreiteter Kampfstil von Kriegern gibt eine Axt in der Haupthand und ein Skramasax in der Schildhand vor.\nSkramasax\nWird beim Aufheben gebunden" }
entries[91009] = { ["name"] = "Renegatenstärke", ["text"] = "Sofort\nErfüllt das Ziel mit der Stärke der Defias. Erhöht verursachten körperlichen Schaden um 200%, reduziert erlittenen Schaden von Zaubern und Fähigkeiten mit Flächenwirkung um 90% und erhöht die Gesundheit um 300%." }
entries[91011] = { ["name"] = "Item - Proc Spell Power On Dmg", ["text"] = "Eure offensiven Zauber haben eine Chance, Eure Zaubermacht 20 Sek. lang um 1926 zu erhöhen.\n(Procchance: 20%, 1.667Min. Abklingzeit)" }
entries[91012] = { ["name"] = "Zündzeug", ["text"] = "Wirken in 3 sek. 5\nDieses einfache Paar von Feuerstein und Stahl wurde zum Feuerschlagen genutzt. Die Halterung des Stabes ist wie ein Drachenkopf geformt, die flache Metallklinge zeigt ein stilisiertes Fischmotiv.\nZündzeug\nWird beim Aufheben gebunden" }
entries[91013] = { ["name"] = "Zeitwurzel", ["text"] = "Sofort\nErhöht Eure Zaubermacht 15 Sek. lang um 1926." }
entries[91014] = { ["name"] = "Zahnbesetzte Umhangfibel", ["text"] = "Wirken in 3 sek. 5\nDiese Gewandschließe diente einst dazu, den schweren Umhang eines Vrykul um die Schultern zu befestigen. An dem kreuzförmigen Bügel sind zwei große, jedoch abgestumpfte Zähne angebracht. Sie stammen wahrscheinlich von einem gealterten Protodrachen. Es ist unklar, ob der Besitzer eine Zuneigung zu dem alten Drachen hatte oder ob die Kreatur die einzige war, die er bezwingen konnte.\nZahnbesetzte Umhangfibel\nWird beim Aufheben gebunden" }
entries[91017] = { ["name"] = "Welle der Heilung", ["text"] = "145 Mana 40 Meter Reichweite\nWirken in 3 sek.\nRuft Naturmagie herbei, um einen Verbündeten zu heilen." }
entries[91018] = { ["name"] = "Kettenheilung", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nErfüllt einen verwundeten Verbündeten mit Heilenergie, die sich auf einen anderen in der Nähe befindlichen Verbündeten ausbreitet. Der Zauber wirkt sich auf bis zu 3 Ziele aus, aber die Heilenergie wird bei jedem folgenden Ziel um 50% reduziert." }
entries[91019] = { ["name"] = "Seelenkraft", ["text"] = "Sofort\nErhöht Eure Zaubermacht 20 Sek. lang um 1926." }
entries[91020] = { ["name"] = "Eissturm", ["text"] = "Sofort\nFügt allen Feinden, die sich im Bereich eines Eisfeldes aufhalten, alle 0.5 Sek. 7000 Frostschaden zu. Dieser Effekt hält an, so lange sich das Ziel in diesem Bereich aufhält." }
