entries[91132] = { ["name"] = "Abdruck eines Krakententakels", ["text"] = "Wirken in 3 sek. 5\nDiese gewaltigen Tintenfische sind Diener von Neptulon dem Gezeitenjäger und ihr heimisches Gewässer ist der Meeresschlund, nicht die Ozeane von Azeroth. Der Fakt, dass dieser Abdruck in fossilem Gestein erhalten ist, legt den Gedanken nahe, dass die mächtigen Kreaturen diese Welt seit Jahrtausenden heimsuchen.\nAbdruck eines Krakententakels\nWird beim Aufheben gebunden" }
entries[91133] = { ["name"] = "Spinnenartige Sonnenuhr", ["text"] = "Wirken in 3 sek. 5\nDiese Artefakt ist eindeutig aus nerubischer Herstellung. Seltsam, denn wozu sollten die unterirdisch lebenden Spinnenlords eine Sonnenuhr gebraucht haben. Könnte sie möglicherweise auf ein leuchtendes, unterirdisches Minreal abgestimmt sein? Vielleicht datiert sie auch auf eine Zeit vor der Zerstörung von Azj'Aqir zurück, bevor die Neruber und Qiraji sich trennten.\nSpinnenartige Sonnenuhr\nWird beim Aufheben gebunden" }
