entries[91188] = { ["name"] = "Verseuchter Rubinring", ["text"] = "Wirken in 3 sek. 5\nDieser Ring ist sowohl schön als auch verstörend. Innerhalb des riesigen, glasklaren Rubins könnt Ihr eine Myriade winziger Kreaturen erkennen, Spinnen oder Milben vielleicht, die unablässig versuchen, aus ihrem roten Gefängnis auszubrechen.\nVerseuchter Rubinring\nWird beim Aufheben gebunden" }
