entries[91197] = { ["name"] = "Simsstein mit sechs Klauen", ["text"] = "Wirken in 3 sek. 5\nDieses steinerne Objekt war vermutlich Teil einer schmückenden Auskragung an einem Wall oder einem Turm des dunklen Azjol-Nerub. Es stellt eine Kreatur dar, die halb Spinne und halb Insekt zu sein scheint und wurde mit grünen, violetten und goldenen Farben lackiert, die schwach fluoreszieren.\nSimsstein mit sechs Klauen\nWird beim Aufheben gebunden" }
entries[91198] = { ["name"] = "Weisheit des Veteranen", ["text"] = "Sofort\nErhöht die Willenskraft 20 Sek. lang um 1926." }
entries[91199] = { ["name"] = "REUSE IN 4.1 Item - Proc Spirit", ["text"] = "Eure Heilzauber gewähren eine Chance, Eure Willenskraft 20 Sek. lang um 1926 zu erhöhen.\n(Procchance: 10%, 1.667Min. Abklingzeit)" }
