entries[91289] = { ["name"] = "Knochenschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 wirbelnden Knochen umgeben. Solange wenigstens 1 Knochen verbleibt, wird der erlittene Schaden um 20% verringert und der mit allen Angriffen, Zaubern und Fähigkeiten verursachte Schaden um 2% erhöht. Jeder erfolgreiche, Schaden verursachende Angriff verbraucht 1 Knochen. Hält 5 Min. lang an.\n(2s Abklingzeit)" }
