entries[91768] = { ["name"] = "Agatha beschwören" }
entries[91769] = { ["name"] = "Schattensichel", ["text"] = "Wirken in 3 sek. 5\nDiese Art kreisrunder Klingen wird seit Ewigkeiten von nachtelfischen Wachen bevorzugt. Eine bekannte Trägerin dieses Waffentyps war Maiev Schattensang, jedoch werden die Klingen auch heute noch von Nachtelfen genutzt, beispielsweise den Tiefenwächtern der Grabhügel des Hyjal. Es ist wahrscheinlich, dass die von Euch gefundene Waffe magische Qualitäten aufwies, bevor sie in so viele Fragmente zerbrach.\nSchattensichel\nWird beim Aufheben gebunden" }
entries[91770] = { ["name"] = "Signal Flare 01" }
entries[91771] = { ["name"] = "Irrwischgestalt", ["text"] = "Sofort\nNehmt 20 Sek. lang eine Irrwischgestalt an." }
entries[91773] = { ["name"] = "Irrwischamulett", ["text"] = "Wirken in 3 sek. 15\nIrrwische sind Naturgeister, angeblich verstorbene Nachtelfen. Sie haben eine starke Verbindung zu den Wäldern ihrer Heimat sowie den Nachtelfen im allgemeinen und führen für sie dienliche Dinge aus, wie die Konstruktion oder Reparatur von Bauten und die Verteidigung elfischer Gemeinschaften. Viele Irrwische opferten sich am Ende des Dritten Krieges, um Archimondes Zerstörung herbeizuführen, dadurch gibt es heutzutage weniger Irrwische, als einst.\nIrrwischamulett\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Nehmt 20 Sek. lang eine Irrwischgestalt an. (10 Min Abklingzeit)" }
entries[91774] = { ["name"] = "Signal Flare 01 Kill Credit" }
entries[91775] = { ["name"] = "Sandburg", ["text"] = "Wirken in 3 sek. 5\nDas ist eine kleine, rechteckige Festung aus Sand. Die Form der Türme und das Sonnenmotiv deuten auf Architektur der Tol'vir hin, eine entsprechende Festung in realem Maßstab habt Ihr jedoch noch nicht in Uldum gesehen. Das Objekt ist tatsächlich aus Sand, nicht Sandstein und Ihr seid Euch nicht sicher, wovon es zusammengehalten wird.\nSandburg\nWird beim Aufheben gebunden" }
entries[91776] = { ["name"] = "Klaue", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nBeharkt einen Gegner mit Klauen und verursacht so 125% des normalen Nahkampfschadens." }
entries[91777] = { ["name"] = "Tirisfal Guardian Aura" }
entries[91778] = { ["name"] = "Klauenfeger", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nSchlägt mit deformierten Klauen nach dem Ziel, welche ihm und bis zu 2 zusätzlichen Zielen 150% des normalen Schadens zufügen." }
entries[91779] = { ["name"] = "Katzenstatuette mit Smaragdaugen", ["text"] = "Wirken in 3 sek. 5\nDie kleine tönerne Katze ist in lebensechter Position und mit regem Ausdruck dargestellt. Auf der Unterseite steht geschrieben, 'In Erinnerung an Chalyx, geliebtes Haustier des Imperators Ninjter.'\nKatzenstatuette mit Smaragdaugen\nWird beim Aufheben gebunden" }
entries[91780] = { ["name"] = "Skarabäushalskette aus Speckstein", ["text"] = "Wirken in 3 sek. 5\n'Imperator Ninjter am Tage seiner Thronbesteigung überreicht. Wir erwarten unter seiner Herrschaft nur Größe.'\nSkarabäushalskette aus Speckstein\nWird beim Aufheben gebunden" }
entries[91781] = { ["name"] = "Signal Flare 02" }
entries[91782] = { ["name"] = "Winziges Oasenmosaik", ["text"] = "Wirken in 3 sek. 5\nDieses kleine Kunstwerk habt Ihr aus seinen vielen kleinen verstreuten Tonkacheln wieder zusammengesetzt, seine satten Farben leuchten Euch türkiswasserblau, palmengrün und sandgelb entgegen.\n\n\"Unsere Hoffnung und Gebete für Imperator Ninjter, möge er der Hungersnot ein Ende setzen und den Ruhm der Ramkahen erneuern!\"\nWinziges Oasenmosaik\nWird beim Aufheben gebunden" }
